using System;
using System.IO;
using System.Drawing;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Net.Http;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace ZapretManager {
public class UpdateForm:Form {
 readonly TextBox token=new TextBox {UseSystemPasswordChar=true,Width=620};readonly TextBox details=new TextBox {Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};readonly Button check=new Button {Text="Проверить релиз",AutoSize=true};readonly Button download=new Button {Text="Скачать проверенный установщик",AutoSize=true,Enabled=false};Dictionary<string,object> asset;readonly HttpClient client=new HttpClient {Timeout=TimeSpan.FromSeconds(30)};bool closed;
 const string Repo="ivanmorkovka1-ux/zaper2";
 public UpdateForm(){Text="Обновление приложения";Size=new Size(850,580);StartPosition=FormStartPosition.CenterParent;Padding=new Padding(18);var top=new FlowLayoutPanel {Dock=DockStyle.Top,Height=165};top.Controls.Add(new Label {Text="Репозиторий: "+Repo+". Для приватного репозитория нужен ваш токен с чтением Contents. Токен используется только в этом окне и не сохраняется.",Width=790,Height=60});top.Controls.Add(token);top.Controls.Add(check);top.Controls.Add(download);var page=new Button {Text="Открыть Releases",AutoSize=true};page.Click+=(s,e)=>Process.Start(new ProcessStartInfo("https://github.com/"+Repo+"/releases") {UseShellExecute=true});top.Controls.Add(page);var local=new Button {Text="Установить скачанный файл…",AutoSize=true};local.Click+=(s,e)=>{using(var picker=new OpenFileDialog {Filter="Установщик Zapret 2 (*.exe)|*.exe"})if(picker.ShowDialog(this)==DialogResult.OK)Install(picker.FileName);};top.Controls.Add(local);Controls.Add(details);Controls.Add(top);UiTheme.Apply(this);details.Text="Текущая версия: "+System.Reflection.Assembly.GetExecutingAssembly().GetName().Version+"\r\nЗапуск установщика сохраняет настройки. Новую версию можно скачать через GitHub в браузере и выбрать здесь.\r\nСторонние обновления движка проверяются отдельной кнопкой главного окна.";client.DefaultRequestHeaders.UserAgent.ParseAdd("Zapret2Manager/3.8.1");check.Click+=async(s,e)=>await Check();download.Click+=async(s,e)=>await Download();FormClosed+=(s,e)=>{closed=true;token.Clear();client.Dispose();};}
 async Task Check(){check.Enabled=download.Enabled=false;asset=null;try{using(var request=new HttpRequestMessage(HttpMethod.Get,"https://api.github.com/repos/"+Repo+"/releases/latest")){if(!string.IsNullOrWhiteSpace(token.Text))request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token.Text.Trim());using(var response=await client.SendAsync(request)){if(closed)return;if((int)response.StatusCode==404){details.Text="Релиз не найден или нет доступа к приватному репозиторию. Откройте Releases в браузере либо укажите токен с доступом к этому репозиторию.";return;}if(!response.IsSuccessStatusCode){details.Text="GitHub вернул HTTP "+(int)response.StatusCode+". Проверьте доступ или повторите позже.";return;}var data=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<Dictionary<string,object>>(await response.Content.ReadAsStringAsync());if(closed)return;string tag=Convert.ToString(data["tag_name"]);details.Text="Релиз: "+tag+"\r\n\r\n"+Convert.ToString(data["body"]);var assets=(object[])data["assets"];asset=assets.Cast<Dictionary<string,object>>().FirstOrDefault(a=>Convert.ToString(a["name"]).StartsWith("Zapret2Manager-Setup-",StringComparison.Ordinal)&&Convert.ToString(a["name"]).EndsWith("-x64.exe",StringComparison.OrdinalIgnoreCase));string digest=asset!=null&&asset.ContainsKey("digest")?Convert.ToString(asset["digest"]):"";download.Enabled=System.Text.RegularExpressions.Regex.IsMatch(digest,@"^sha256:[0-9a-fA-F]{64}$");if(!download.Enabled)details.AppendText("\r\n\r\nАвтозагрузка недоступна: нет Windows-установщика с SHA-256 в метаданных GitHub. Используйте Releases в браузере.");}}}catch(Exception){if(!closed)details.Text="Не удалось проверить GitHub. Проверьте подключение и доступ к репозиторию.";}finally{if(!closed)check.Enabled=true;}}
 async Task Download(){if(asset==null)return;using(var picker=new SaveFileDialog {FileName=Path.GetFileName(Convert.ToString(asset["name"])),Filter="Установщик (*.exe)|*.exe"}){if(picker.ShowDialog(this)!=DialogResult.OK)return;download.Enabled=false;string temp=picker.FileName+"."+Guid.NewGuid().ToString("N")+".part";try{using(var request=new HttpRequestMessage(HttpMethod.Get,"https://api.github.com/repos/"+Repo+"/releases/assets/"+Convert.ToString(asset["id"]))){request.Headers.Accept.ParseAdd("application/octet-stream");if(!string.IsNullOrWhiteSpace(token.Text))request.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",token.Text.Trim());using(var response=await client.SendAsync(request)){response.EnsureSuccessStatusCode();using(var file=File.Create(temp))await response.Content.CopyToAsync(file);}}using(var sha=System.Security.Cryptography.SHA256.Create())using(var file=File.OpenRead(temp)){string hash=BitConverter.ToString(sha.ComputeHash(file)).Replace("-","");if(!string.Equals("sha256:"+hash,Convert.ToString(asset["digest"]),StringComparison.OrdinalIgnoreCase))throw new Exception("SHA-256 скачанного файла не совпадает с метаданными GitHub");}if(closed)return;File.Copy(temp,picker.FileName,true);details.AppendText("\r\nSHA-256 проверена. Файл сохранён: "+picker.FileName);Install(picker.FileName);}catch(Exception e){if(!closed)details.Text="Скачивание не завершено: "+e.Message;}finally{if(File.Exists(temp))File.Delete(temp);if(!closed)download.Enabled=true;}}}
 void Install(string path){try{if(Core.OperationGate.CurrentCount==0)throw new Exception("Дождитесь завершения операции в приложении");Core.Guard();var version=FileVersionInfo.GetVersionInfo(path);if(!string.Equals((version.ProductName??"").Trim(),"Zapret 2 Manager",StringComparison.OrdinalIgnoreCase)&&!string.Equals((version.ProductName??"").Trim(),"Zaper",StringComparison.OrdinalIgnoreCase))throw new Exception("У выбранного файла нет ожидаемого имени установщика Zapret 2 Manager");if(MessageBox.Show(this,"Запустить выбранный установщик?\r\n"+path+"\r\nВерсия: "+version.ProductVersion+"\r\nПанель будет закрыта, настройки сохраняет установщик.","Обновление",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;Process.Start(new ProcessStartInfo(path) {UseShellExecute=true,Verb="runas"});var main=Owner as MainForm;Close();if(main!=null)main.ExitApp();}catch(Exception e){MessageBox.Show(this,e.Message,"Обновление не запущено");}}
}
}
